                                                                                                                                                                                                          
  CREATE TABLE "CHECK_FORM_ITEM"                                                                                                                                                               
   (	"FORM_ITEM_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
