	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                    
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                               
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                     
	"REMARK" NVARCHAR2(512),                                                                                                                                                                                 
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                      
	"FORM_ID" NUMBER(20,0) NOT NULL ENABLE,                                                                                                                                                                  
	"NAME" NVARCHAR2(512),                                                                                                                                                                                   
	"TYPE" NVARCHAR2(20),                                                                                                                                                                                    
	"NUMBER_VALUE_MAX" NUMBER(20,9),                                                                                                                                                                         
	"NUMBER_VALUE_MIN" NUMBER(20,9),                                                                                                                                                                         
	"NUMBER_UNIT" NVARCHAR2(20),                                                                                                                                                                             
	"ABNORMAL_SHOW" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                   
	"IMAGE_SHOW" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                      
	"IMAGE_NUM" NUMBER(3,0),                                                                                                                                                                                 
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                       
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                            
